"use strict";
// Synthetic Prisma-like client (CJS): reads a schema at startup, reads an env var, queries
// a JSON "database" through fs.promises, and uses crypto for request ids.
const fs = require("fs");
const fsp = require("node:fs/promises");
const crypto = require("node:crypto");
const path = require("path");

class OrmClient {
  constructor(dir) {
    this.dir = dir;
    this.url = process.env.DATABASE_URL || "file:./data/db.json";
    this.apiKey = process.env.PRISMA_API_KEY || null;
    this.schema = fs.readFileSync(path.join(dir, "schema.prisma"), "utf8");
  }
  async findMany(model) {
    const text = await fs.promises.readFile(path.join(this.dir, "db.json"), "utf8");
    const stat = await fsp.stat(path.join(this.dir, "db.json"));
    return { requestId: crypto.randomUUID(), size: stat.size, rows: JSON.parse(text)[model] };
  }
}

module.exports = { OrmClient, fs, fsp };
